def build_demand_structure_frame() -> pd.DataFrame:
    rows: list[dict[str, Any]] = []
    for index, quarter in enumerate(DEMAND_QUARTERS):
        quarter_number = int(quarter[1])
        year = 2000 + int(quarter[-2:])
        date_value = pd.Period(f"{year}Q{quarter_number}", freq="Q").end_time.normalize()
        for category in DEMAND_CATEGORIES:
            rows.append({
                "date": date_value,
                "quarter": quarter,
                "category": category,
                "demand_share": DEMAND_SHARE[category][index],
                "demand_12m_change_tn": DEMAND_12M_CHANGE[category][index],
            })
    frame = pd.DataFrame(rows)
    frame["demand_share"] = pd.to_numeric(frame["demand_share"], errors="coerce")
    frame["demand_12m_change_tn"] = pd.to_numeric(frame["demand_12m_change_tn"], errors="coerce")
    return frame

